class Solution:
    def minimumTime(self, nums1: List[int], nums2: List[int], x: int) -> int:
        n = len(nums1)
        current_sum = sum(nums1)
        if current_sum <= x:
            return 0
        t = 0
        while current_sum > x:
            t += 1
            for i in range(n):
                nums1[i] += nums2[i]
            # find index of current maximum
            max_idx = 0
            max_val = nums1[0]
            for i in range(1, n):
                if nums1[i] > max_val:
                    max_val = nums1[i]
                    max_idx = i
            # set that index to zero and update sum
            current_sum -= max_val
            nums1[max_idx] = 0
        return t

