class Solution:
    def maxIncreasingGroups(self, usageLimits: List[int]) -> int:
        # Work on a sorted copy to avoid mutating the input
        try:
            arr = sorted(usageLimits)
        except TypeError:
            # In case of invalid/mixed types, filter to integers only
            arr = sorted([v for v in usageLimits if isinstance(v, int)])

        next_size = 1
        groups = 0

        for limit in arr:
            if not isinstance(limit, int) or limit < 0:
                continue
